import{_ as e,o,c as s,ae as n}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"Análisis Financiero","description":"","frontmatter":{},"headers":[],"relativePath":"admin/finanzas.md","filePath":"admin/finanzas.md"}'),t={name:"admin/finanzas.md"};function r(i,a,l,c,d,g){return o(),s("div",null,[...a[0]||(a[0]=[n('<h1 id="analisis-financiero" tabindex="-1">Análisis Financiero <a class="header-anchor" href="#analisis-financiero" aria-label="Permalink to &quot;Análisis Financiero&quot;">​</a></h1><h2 id="estructura-de-costos-wasabi-s3" tabindex="-1">Estructura de Costos (Wasabi S3) <a class="header-anchor" href="#estructura-de-costos-wasabi-s3" aria-label="Permalink to &quot;Estructura de Costos (Wasabi S3)&quot;">​</a></h2><p>Wasabi tiene un costo fijo simple de <strong>$6.99 USD por 1 TB (1024 GB) al mes</strong>.</p><ul><li><strong>Costo por GB:</strong> $0.0068 USD.</li><li><strong>Tipo de Cambio Sugerido:</strong> S/. 3.80 por $1 USD.</li><li><strong>Costo Real por GB en Soles:</strong> S/. 0.026.</li></ul><h3 id="ejemplo-de-costo-por-retencion-7-dias" tabindex="-1">Ejemplo de Costo por Retención (7 Días) <a class="header-anchor" href="#ejemplo-de-costo-por-retencion-7-dias" aria-label="Permalink to &quot;Ejemplo de Costo por Retención (7 Días)&quot;">​</a></h3><p>Gracias a la <strong>Deduplicación de Restic</strong>, retener 7 días de backup de una fuente de 100GB no consume 700GB.</p><ul><li><strong>Día 1 (Full):</strong> 100 GB.</li><li><strong>Días 2-7 (Deltas del 1%):</strong> 1 GB x 6 = 6 GB.</li><li><strong>Total Ocupado:</strong> ~106 GB.</li><li><strong>Costo en Wasabi:</strong> $0.74 USD (<strong>S/. 2.80 mensuales</strong>).</li></ul><h2 id="proyeccion-de-planes-y-ganancias" tabindex="-1">Proyección de Planes y Ganancias <a class="header-anchor" href="#proyeccion-de-planes-y-ganancias" aria-label="Permalink to &quot;Proyección de Planes y Ganancias&quot;">​</a></h2><h3 id="🥉-plan-start-hostings-pequenos" tabindex="-1">🥉 Plan Start (Hostings pequeños) <a class="header-anchor" href="#🥉-plan-start-hostings-pequenos" aria-label="Permalink to &quot;🥉 Plan Start (Hostings pequeños)&quot;">​</a></h3><ul><li><strong>Capacidad:</strong> 10 GB.</li><li><strong>Precio de Venta:</strong> S/. 15.00 / mes.</li><li><strong>Costo Wasabi:</strong> S/. 0.30.</li><li><strong>Ganancia Bruta:</strong> S/. 14.70 (<strong>98% de Margen</strong>).</li></ul><h3 id="🥈-plan-pro-recomendado-para-vps" tabindex="-1">🥈 Plan Pro (Recomendado para VPS) <a class="header-anchor" href="#🥈-plan-pro-recomendado-para-vps" aria-label="Permalink to &quot;🥈 Plan Pro (Recomendado para VPS)&quot;">​</a></h3><ul><li><strong>Capacidad:</strong> 100 GB.</li><li><strong>Precio de Venta:</strong> S/. 50.00 / mes.</li><li><strong>Costo Wasabi:</strong> S/. 2.80.</li><li><strong>Ganancia Bruta:</strong> S/. 47.20 (<strong>94% de Margen</strong>).</li></ul><h3 id="🥇-plan-enterprise" tabindex="-1">🥇 Plan Enterprise <a class="header-anchor" href="#🥇-plan-enterprise" aria-label="Permalink to &quot;🥇 Plan Enterprise&quot;">​</a></h3><ul><li><strong>Capacidad:</strong> 500 GB.</li><li><strong>Precio de Venta:</strong> S/. 120.00 / mes.</li><li><strong>Costo Wasabi:</strong> S/. 14.00.</li><li><strong>Ganancia Bruta:</strong> S/. 106.00 (<strong>88% de Margen</strong>).</li></ul><h2 id="optimizacion-de-costos-wasabi-best-practices" tabindex="-1">Optimización de Costos (Wasabi Best Practices) <a class="header-anchor" href="#optimizacion-de-costos-wasabi-best-practices" aria-label="Permalink to &quot;Optimización de Costos (Wasabi Best Practices)&quot;">​</a></h2><ol><li><strong>Auto-Pruning:</strong> Se implementará el comando <code>restic forget --keep-daily 7 --prune</code>. Esto asegura que los datos de más de 7 días se borren físicamente, liberando espacio y bajando tu factura.</li><li><strong>Mínimo de Facturación:</strong> Wasabi cobra un mínimo de 1 TB si el total de tus buckets es menor a eso. <ul><li><em>Estrategia:</em> Debes tener al menos 10 clientes del Plan Pro (100GB cada uno) para empezar a pagar exactamente lo que consumes.</li></ul></li><li><strong>Sin cargo por Egress:</strong> Wasabi no cobra por descargar datos (restauraciones), lo cual hace que tus costos sean <strong>predecibles</strong>.</li></ol>',16)])])}const m=e(t,[["render",r]]);export{u as __pageData,m as default};
